// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/cookie/domains", wrapper.CookieListDomains)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/cookie/domains", wrapper.CookieRegisterDomain)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/cookie/domains/{id}", wrapper.CookieGetDomain)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/cookie/domains/{id}/verify", wrapper.CookieVerifyDomain)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/cookie/categories", wrapper.CookieListCategories)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/cookie/categories", wrapper.CookieCreateCategory)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/admin/v1/cookie/categories/{id}", wrapper.CookieDeleteCategory)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/cookie/domains/{id}/banner-configs", wrapper.CookieListBannerConfigs)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/cookie/domains/{id}/banner-configs", wrapper.CookieCreateBannerConfig)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/cookie/banner-configs/{id}", wrapper.CookieGetBannerConfig)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/v1/cookie/banner-configs/{id}", wrapper.CookieUpdateBannerConfigDraft)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/cookie/banner-configs/{id}/publish", wrapper.CookiePublishBannerConfig)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/cookie/domains/{id}/cookies", wrapper.CookieListCookies)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/cookie/domains/{id}/cookies", wrapper.CookieCreateCookie)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/admin/v1/cookie/cookies/{id}", wrapper.CookieDeleteCookie)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/cookie/domains/{id}/script-rules", wrapper.CookieListScriptRules)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/cookie/domains/{id}/script-rules", wrapper.CookieCreateScriptRule)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/admin/v1/cookie/script-rules/{id}", wrapper.CookieDeleteScriptRule)
	})

	return r
}

